# parent.env<-, environmentIsLocked, pos.to.env, compareNumericVersion
show <- function(expr) tryCatch(expr, error = function(e) cat("Error in", deparse(conditionCall(e)), ":", conditionMessage(e), "\n"))
e <- new.env()
p <- new.env()
assign("v", 42, envir = p)
parent.env(e) <- p
identical(parent.env(e), p)
get("v", envir = e)
r <- `parent.env<-`(e, globalenv())
identical(r, e)
identical(parent.env(e), globalenv())
show(parent.env(e) <- 1)
pe <- `parent.env<-`
show(pe(1, e))
show(pe(NULL, e))
show(parent.env(e) <- NULL)
show(pe(emptyenv(), e))
b <- new.env()
lockEnvironment(b)
invisible(pe(b, emptyenv()))
identical(parent.env(b), emptyenv())
show(pe(baseenv(), "a"))
imp <- new.env(parent = asNamespace("base"))
attr(imp, "name") <- "imports:foo"
invisible(pe(imp, e))
invisible(pe(imp, asNamespace("base")))
lockEnvironment(imp)
show(pe(imp, e))
lockEnvironment(p)
parent.env(p) <- e
identical(parent.env(p), e)
# environmentIsLocked
environmentIsLocked(p)
environmentIsLocked(e)
environmentIsLocked(globalenv())
show(environmentIsLocked(1))
show(environmentIsLocked(NULL))
# pos.to.env
identical(pos.to.env(1), globalenv())
identical(pos.to.env(1L), globalenv())
identical(pos.to.env(length(search())), baseenv())
f <- function() pos.to.env(-1)
identical(f(), globalenv())
g <- function() { h <- function() pos.to.env(-1); h() }
identical(environmentName(g()), "R_GlobalEnv")
k <- function() { h <- function() pos.to.env(-1); environment(h) ; identical(h(), environment()) }
k()
l <- pos.to.env(c(1, 1))
length(l)
identical(l[[1]], globalenv())
identical(pos.to.env("1"), globalenv())
show(pos.to.env(0))
show(pos.to.env(-2))
show(pos.to.env(NA))
show(pos.to.env(integer(0)))
show(pos.to.env(1000))
length(pos.to.env(x = 1:2))
show(pos.to.env(y = 1))
identical(pos.to.env(seq_len(1)), globalenv())
# compareNumericVersion
cnv <- function(x, y) .Internal(compareNumericVersion(x, y))
cnv(list(1:3, c(1L, 2L), 2L, integer(0)), list(c(1L, 2L, 3L), c(1L, 2L, 0L, 0L), c(1L, 9L), 1L))
cnv(list(c(1L, 2L, 1L)), list(c(1L, 2L), c(1L, 3L), c(1L, 2L, 1L, 1L)))
cnv(list(), list(1L))
cnv(list(1L), list())
cnv(list(c(2L, 0L)), list(2L))
show(cnv(list(1), list(1L)))
show(cnv(list(1L), list("a")))
show(cnv(1, list(1L)))
show(cnv(quote(x), list(1L)))
show(cnv(list(1L), 1L))
cnv(integer(0), list(1L))
package_version("1.2.3") > "1.2"
numeric_version(c("1.0", "2.1.3", "0.9")) >= "1.0"
